package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;
import org.apache.commons.math3.linear.*;

/** Standardized component/factor moment parameters from available-pair correlations; no case scores. */
public final class PairwiseComponents {
    private PairwiseComponents(){}
    public record Fit(ComponentScores.Model sourceModel,ComponentScores.Model momentModel,boolean consistent,int[] sourceColumns,PairwiseMoments.Fit moments,
                      double[][] weights,double[][] loadings,double[][] paths,double[] rSquared,double[][] constructCorrelations,double[] reliabilities,
                      double[][] totalEffects,boolean converged,int iterations,Double finalWeightChange,Double normalizedObjective,List<String> warnings){
        public Fit{sourceColumns=sourceColumns.clone();weights=Matrices.copy(weights);loadings=Matrices.copy(loadings);paths=Matrices.copy(paths);rSquared=rSquared.clone();constructCorrelations=Matrices.copy(constructCorrelations);reliabilities=reliabilities.clone();totalEffects=Matrices.copy(totalEffects);warnings=List.copyOf(warnings);}
        @Override public int[] sourceColumns(){return sourceColumns.clone();}
        @Override public double[][] weights(){return Matrices.copy(weights);}
        @Override public double[][] loadings(){return Matrices.copy(loadings);}
        @Override public double[][] paths(){return Matrices.copy(paths);}
        @Override public double[] rSquared(){return rSquared.clone();}
        @Override public double[][] constructCorrelations(){return Matrices.copy(constructCorrelations);}
        @Override public double[] reliabilities(){return reliabilities.clone();}
        @Override public double[][] totalEffects(){return Matrices.copy(totalEffects);}
    }
    public record Resampled(Fit point,Bootstrap.Result inference){}
    private record Work(ComponentScores.Model source,ComponentScores.Model local,int[] columns,List<String> names){}
    private static Work prepare(List<String> columns,ComponentScores.Model source,boolean consistent){if(consistent&&source.estimator()!=ComponentScores.Estimator.PLS)throw new IllegalArgumentException("Consistent correction applies to PLS reflective factors, not GSCA.");NonlinearPls.normalizedPaths(source.names(),source.paths(),List.of());LinkedHashSet<Integer> selected=new LinkedHashSet<>();if(source.estimator()==ComponentScores.Estimator.PLS)for(var block:source.blocks())for(int column:block.columns())selected.add(column);else for(int column:source.gscaColumns())selected.add(column);if(selected.size()<2||selected.size()>256||selected.stream().anyMatch(index->index<0||index>=columns.size()))throw new IllegalArgumentException("Select 2–256 valid indicators for pairwise component estimation.");int[] indices=selected.stream().mapToInt(Integer::intValue).toArray();Map<Integer,Integer> positions=new HashMap<>();for(int i=0;i<indices.length;i++)positions.put(indices[i],i);ComponentScores.Model local;if(source.estimator()==ComponentScores.Estimator.PLS){List<PlsSem.Block> blocks=new ArrayList<>();for(var block:source.blocks())blocks.add(new PlsSem.Block(block.name(),Arrays.stream(block.columns()).map(positions::get).toArray(),block.mode(),block.initialWeights(),block.measurementType()));local=ComponentScores.Model.pls(blocks,source.edges(),source.plsOptions());}else local=ComponentScores.Model.gsca(source.gscaModel(),source.gscaOptions(),java.util.stream.IntStream.range(0,indices.length).toArray());return new Work(source,local,indices,Arrays.stream(indices).mapToObj(columns::get).toList());}
    private static double[][] selected(double[][] data,Work work){if(data==null||data.length<3)throw new IllegalArgumentException("At least three original rows are required.");double[][] result=new double[data.length][work.columns.length];for(int row=0;row<data.length;row++){if(data[row]==null)throw new IllegalArgumentException("Missing raw row.");for(int column=0;column<work.columns.length;column++){if(work.columns[column]>=data[row].length)throw new IllegalArgumentException("Pairwise model column lies outside a raw row.");result[row][column]=data[row][work.columns[column]];}}return result;}
    public static Fit fit(double[][] raw,List<String> columns,ComponentScores.Model source,boolean consistent){var work=prepare(columns,source,consistent);return fitSelected(selected(raw,work),work,consistent);}
    private static Fit fitSelected(double[][] raw,Work work,boolean consistent){var moments=PairwiseMoments.fit(raw,work.names);double[][] design=PairwiseMoments.design(moments);int p=work.names.size(),m=work.local.names().size();double[][] weights=new double[p][m],loadings=new double[p][m],paths,correlations;for(var row:weights)Arrays.fill(row,Double.NaN);for(var row:loadings)Arrays.fill(row,Double.NaN);double[] r2,reliabilities=new double[m];Arrays.fill(reliabilities,Double.NaN);boolean converged;int iterations;Double change=null,objective=null;List<String>warnings=new ArrayList<>(moments.warnings());
        if(work.local.estimator()==ComponentScores.Estimator.PLS){PlsSem.Fit point;if(consistent){var corrected=ConsistentPls.fit(design,work.local.blocks(),work.local.edges(),work.local.plsOptions());point=corrected.inferenceFit();correlations=corrected.correlations();reliabilities=corrected.reliabilities();warnings.addAll(corrected.warnings());}else{point=PlsSem.fit(design,work.local.blocks(),work.local.edges(),work.local.plsOptions());correlations=Matrices.covariance(point.scores(),false);}double[][] w=point.weights(),l=point.loadings();for(int j=0;j<m;j++){int[] columns=work.local.blocks().get(j).columns();for(int k=0;k<columns.length;k++){weights[columns[k]][j]=w[j][k];loadings[columns[k]][j]=l[j][k];}}paths=point.pathCoefficients();r2=point.rSquared();converged=point.converged();iterations=point.iterations();change=point.finalWeightChange();}
        else{var point=Gsca.fit(design,work.local.gscaModel(),work.local.gscaOptions());boolean[][] wm=work.local.gscaModel().weights(),lm=work.local.gscaModel().loadings();double[][] w=point.weights(),l=point.loadings();for(int i=0;i<p;i++)for(int j=0;j<m;j++){if(wm[i][j])weights[i][j]=w[i][j];if(lm[i][j])loadings[i][j]=l[i][j];}paths=point.paths();r2=point.rSquared();correlations=point.correlations();converged=point.converged();iterations=point.iterations();objective=point.objective()/design.length;warnings.addAll(point.warnings());}
        double[][] totals=totals(paths);warnings.add("Point parameters depend only on the positive-definite pairwise correlation matrix. A centered covariance-equivalent design is used internally to reuse validated solvers; its artificial rows are never exposed as original observations or case scores.");warnings.add("Weights, measurement coefficients, construct correlations, paths and R-squared are standardized moment estimates. There is no common complete-case score matrix. Score-dependent prediction, IPMA, segmentation and nonlinear/case-score workflows are not silently inferred from pairwise moments.");warnings.add("Original incomplete rows and missingness patterns, not covariance-equivalent rows, are resampled for uncertainty. Any matrix/reliability/nonconvergence failures remain disclosed without replacement.");if(work.local.estimator()==ComponentScores.Estimator.GSCA)warnings.add("GSCA measurement loadings are conditional measurement coefficients under the configured masks, not necessarily simple indicator-score correlations.");if(!converged)warnings.add("Moment-model estimation did not converge; inference is unavailable.");return new Fit(work.source,work.local,consistent,work.columns,moments,weights,loadings,paths,r2,correlations,reliabilities,totals,converged,iterations,change,objective,warnings);
    }
    private static double[][] totals(double[][] paths){int m=paths.length;double[][] b=new double[m][m];for(int i=0;i<m;i++)for(int j=0;j<m;j++)b[i][j]=Double.isFinite(paths[i][j])?paths[i][j]:0;return new LUDecomposition(MatrixUtils.createRealIdentityMatrix(m).subtract(new Array2DRowRealMatrix(b,false))).getSolver().getInverse().subtract(MatrixUtils.createRealIdentityMatrix(m)).getData();}
    public static Resampled bootstrap(double[][] raw,List<String> columns,ComponentScores.Model source,boolean consistent,Bootstrap.Options options,IntConsumer progress){var work=prepare(columns,source,consistent);double[][] data=selected(raw,work);Fit point=fitSelected(data,work,consistent);if(!point.converged)throw new IllegalArgumentException("Pairwise point model did not converge.");var inference=Resampling.run(PairwiseMoments.pack(data),parameters(point),values(point),options,(sample,rows)->{var fitted=fitSelected(PairwiseMoments.unpack(sample),work,consistent);if(!fitted.converged)throw new IllegalArgumentException("Pairwise component fit did not converge.");return values(align(fitted,point));},progress,"Pairwise-moment "+(consistent?"PLSc":source.estimator()),"Shared original incomplete rows are resampled with finite value/missing-mask packing. Every pair count, pair-specific moment and component/factor estimate is recomputed. Moment signs align through indicator covariance with the point-fit weights; no artificial case scores are resampled.");List<String>warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings);return new Resampled(point,new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator()));}
    private static Fit align(Fit fit,Fit reference){int p=fit.weights.length,m=fit.paths.length;double[][] w=fit.weights(),l=fit.loadings(),b=fit.paths(),c=fit.constructCorrelations(),t=fit.totalEffects(),r=fit.moments.correlation();double[] signs=new double[m];for(int j=0;j<m;j++){double cross=0,a=0,z=0;for(int i=0;i<p;i++)for(int k=0;k<p;k++){double x=Double.isFinite(w[i][j])?w[i][j]:0,y=Double.isFinite(w[k][j])?w[k][j]:0,u=Double.isFinite(reference.weights[i][j])?reference.weights[i][j]:0,v=Double.isFinite(reference.weights[k][j])?reference.weights[k][j]:0;cross+=x*r[i][k]*v;a+=x*r[i][k]*y;z+=u*r[i][k]*v;}if(!Double.isFinite(cross)||Math.abs(cross)<=1e-8*Math.sqrt(a*z))throw new IllegalArgumentException("A pairwise component cannot be oriented reliably to the original moment weights.");signs[j]=cross<0?-1:1;for(int i=0;i<p;i++){w[i][j]*=signs[j];l[i][j]*=signs[j];}}for(int i=0;i<m;i++)for(int j=0;j<m;j++){b[i][j]*=signs[i]*signs[j];c[i][j]*=signs[i]*signs[j];t[i][j]*=signs[i]*signs[j];}return new Fit(fit.sourceModel,fit.momentModel,fit.consistent,fit.sourceColumns,fit.moments,w,l,b,fit.rSquared,c,fit.reliabilities,t,fit.converged,fit.iterations,fit.finalWeightChange,fit.normalizedObjective,fit.warnings);}
    public static List<Bootstrap.Parameter> parameters(Fit fit){List<Bootstrap.Parameter> result=new ArrayList<>();var names=fit.momentModel.names();for(var edge:fit.momentModel.paths())result.add(new Bootstrap.Parameter("Structural path",edge.source(),edge.target(),-1,names.get(edge.source())+" -> "+names.get(edge.target())));for(int i=0;i<fit.weights.length;i++)for(int j=0;j<names.size();j++){if(Double.isFinite(fit.weights[i][j]))result.add(new Bootstrap.Parameter("Measurement weight",j,j,i,fit.moments.names().get(i)));if(Double.isFinite(fit.loadings[i][j]))result.add(new Bootstrap.Parameter("Measurement loading",j,j,i,fit.moments.names().get(i)));}for(int j=0;j<names.size();j++){if(Double.isFinite(fit.rSquared[j]))result.add(new Bootstrap.Parameter("R squared",j,j,-1,names.get(j)));if(fit.consistent&&fit.momentModel.blocks().get(j).measurementType()==PlsSem.MeasurementType.REFLECTIVE&&fit.momentModel.blocks().get(j).columns().length>1)result.add(new Bootstrap.Parameter("PLSc rho A",j,j,-1,names.get(j)));}for(int i=0;i<names.size();i++)for(int j=i+1;j<names.size();j++)result.add(new Bootstrap.Parameter("Construct correlation",i,j,-1,names.get(i)+" / "+names.get(j)));boolean[][] reachable=new boolean[names.size()][names.size()];for(var edge:fit.momentModel.paths())reachable[edge.source()][edge.target()]=true;for(int k=0;k<names.size();k++)for(int i=0;i<names.size();i++)for(int j=0;j<names.size();j++)reachable[i][j]|=reachable[i][k]&&reachable[k][j];for(int i=0;i<names.size();i++)for(int j=0;j<names.size();j++)if(i!=j&&reachable[i][j]){result.add(new Bootstrap.Parameter("Total structural effect",i,j,-1,names.get(i)+" -> "+names.get(j)));boolean indirect=false;for(int k=0;k<names.size();k++)if(k!=i&&k!=j&&reachable[i][k]&&reachable[k][j])indirect=true;if(indirect)result.add(new Bootstrap.Parameter("Indirect structural effect",i,j,-1,names.get(i)+" -> "+names.get(j)));}return List.copyOf(result);}
    public static double[] values(Fit fit){List<Double> out=new ArrayList<>();for(var parameter:parameters(fit))out.add(switch(parameter.family()){case "Structural path"->fit.paths[parameter.source()][parameter.target()];case "Measurement weight"->fit.weights[parameter.column()][parameter.target()];case "Measurement loading"->fit.loadings[parameter.column()][parameter.target()];case "R squared"->fit.rSquared[parameter.target()];case "PLSc rho A"->fit.reliabilities[parameter.target()];case "Construct correlation"->fit.constructCorrelations[parameter.source()][parameter.target()];case "Total structural effect"->fit.totalEffects[parameter.source()][parameter.target()];case "Indirect structural effect"->fit.totalEffects[parameter.source()][parameter.target()]-(Double.isFinite(fit.paths[parameter.source()][parameter.target()])?fit.paths[parameter.source()][parameter.target()]:0);default->throw new IllegalArgumentException("Unknown pairwise parameter.");});return out.stream().mapToDouble(Double::doubleValue).toArray();}
}
